import{_ as e,o,c as a,a2 as r}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"Troubleshoot","description":"MiniTavern ↔ Ollama/LM Studio — Test failures, timeouts, CORS, firewall, and other common issues with fixes.","frontmatter":{"title":"Troubleshoot","description":"MiniTavern ↔ Ollama/LM Studio — Test failures, timeouts, CORS, firewall, and other common issues with fixes.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Troubleshoot · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern ↔ Ollama/LM Studio — Test failures, timeouts, CORS, firewall, and other common issues with fixes."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/troubleshoot"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/troubleshoot"}]]},"headers":[],"relativePath":"en/troubleshoot.md","filePath":"en/troubleshoot.md","lastUpdated":1787224147000}'),l={name:"en/troubleshoot.md"};function d(i,t,n,s,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="troubleshoot" tabindex="-1">Troubleshoot <a class="header-anchor" href="#troubleshoot" aria-label="Permalink to &quot;Troubleshoot&quot;">​</a></h1><p>Find by symptom. If still stuck: App <strong>Settings → Help &amp; feedback → Report an issue</strong> (screenshots and issue logs welcome), or the <strong>feedback email</strong>. Include: OS, tool (Ollama / LM Studio / KoboldCPP, etc.), Base URL (you may mask the last two IP octets), and the exact error text.</p><h2 id="connection-test" tabindex="-1">Connection / Test <a class="header-anchor" href="#connection-test" aria-label="Permalink to &quot;Connection / Test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Timeout</td><td>Not same Wi‑Fi, firewall blocking port, service not on <code>0.0.0.0</code></td><td>Same network; allow port; follow each tool’s “start server / LAN” chapter</td></tr><tr><td>Instant fail / cannot connect</td><td>Wrong IP/port, service off</td><td>On PC open <code>http://IP:port/v1/models</code>; check Base URL</td></tr><tr><td><code>localhost</code> still fails</td><td>On the phone, localhost is the phone</td><td>Use the PC LAN IP</td></tr><tr><td>401 / key error</td><td>A few local stacks validate Key</td><td>Any non-empty placeholder, or disable auth per that tool’s docs</td></tr><tr><td>404 / model not found</td><td>Name mismatch</td><td>Copy the <strong>full id</strong> from <code>ollama list</code> or <code>/v1/models</code></td></tr><tr><td>Response but empty chat / error</td><td>Compatibility, short timeout, model not loaded</td><td>Raise timeout; confirm model loaded; try a smaller model</td></tr></tbody></table><h2 id="network-and-system" tabindex="-1">Network and system <a class="header-anchor" href="#network-and-system" aria-label="Permalink to &quot;Network and system&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>PC works, phone does not</td><td>Guest Wi‑Fi / AP isolation</td><td>Use main network; or phone hotspot with PC joined</td></tr><tr><td>Occasional disconnect</td><td>PC sleep, IP changed</td><td>Prevent sleep; re-check IP and update the link</td></tr><tr><td>Breaks with VPN on</td><td>Routing / virtual NIC</td><td>Disable VPN for the test or exclude LAN</td></tr></tbody></table><h2 id="url-format" tabindex="-1">URL format <a class="header-anchor" href="#url-format" aria-label="Permalink to &quot;URL format&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Correct</th><th>Incorrect</th></tr></thead><tbody><tr><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://localhost:11434/v1</code></td></tr><tr><td><code>http://192.168.1.8:1234/v1</code></td><td><code>http://192.168.1.8:1234/v1/chat/completions</code></td></tr><tr><td><code>http://192.168.1.8:5001/v1</code></td><td><code>https://192.168.1.8:11434/v1</code> (do not force https without local certs)</td></tr><tr><td><code>http://192.168.1.8:8080/v1</code></td><td></td></tr></tbody></table><h2 id="cleartext-http" tabindex="-1">Cleartext HTTP <a class="header-anchor" href="#cleartext-http" aria-label="Permalink to &quot;Cleartext HTTP&quot;">​</a></h2><p>MiniTavern <strong>Android</strong> allows cleartext HTTP (common on LAN). If still blocked:</p><ul><li>Confirm Base URL is <code>http://</code>, not a wrong scheme</li><li>Confirm OS / vendor network protection is not blocking LAN</li><li>On iOS ATS issues, prefer the LAN address in the docs; if it still fails, report OS version and error</li></ul><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>CORS mainly affects browser pages; <strong>native App → API is usually not affected by CORS</strong>. If a browser front-end on the PC fails, that does not mean MiniTavern will — trust in-App Test.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>First token very slow</td><td>Smaller quant / params; confirm GPU is used</td></tr><tr><td>Stalls mid-generation</td><td>Raise timeout; close other VRAM users; check PC logs for OOM</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/manual/errors">Manual · Error codes</a> (Test / chat API errors)</li><li><a href="/ultra_guides/en/quickstart">30-minute quickstart</a></li><li><a href="/ultra_guides/en/local/tools">Tools overview</a> · <a href="/ultra_guides/en/local/models">Recommended models</a></li><li><a href="/ultra_guides/en/ollama/lan">Ollama LAN</a></li><li><a href="/ultra_guides/en/lmstudio/server">LM Studio Local Server</a></li><li><a href="/ultra_guides/en/koboldcpp/server">KoboldCPP API</a></li><li><a href="/ultra_guides/en/llamacpp/server">llama.cpp server</a></li><li><a href="/ultra_guides/en/connect-app/minitavern">MiniTavern config</a></li></ul>',17)])])}const p=e(l,[["render",d]]);export{m as __pageData,p as default};
